class OperationsMixin:
    """A method for each operation: path parameters first, then the body, then keyword options (query, if_match, preview, idempotency_key)."""

    def accept_quote(self, quote_id, body=None, **options):
        """Record that the customer accepted a quote (POST /v1/quotes/{quote_id}/accept; scopes fyniq.write.sales)."""
        return self.call("acceptQuote", [quote_id], body, **options)

    def add_subscription_contract_evidence(self, contract_id, body=None, **options):
        """Attach a file to a subscription contract or one of its amendments (POST /v1/subscription-contracts/{contract_id}/evidence; scopes fyniq.write.sales)."""
        return self.call("addSubscriptionContractEvidence", [contract_id], body, **options)

    def amend_subscription_contract(self, contract_id, body=None, **options):
        """Amend a subscription contract from a day (POST /v1/subscription-contracts/{contract_id}/amendments; scopes fyniq.write.sales)."""
        return self.call("amendSubscriptionContract", [contract_id], body, **options)

    def apply_credit(self, body=None, **options):
        """Apply a supplier credit to a bill (POST /v1/credit-applications; scopes fyniq.write.purchases)."""
        return self.call("applyCredit", [], body, **options)

    def apply_customer_credit(self, body=None, **options):
        """Apply a customer credit to an invoice (POST /v1/customer-credit-applications; scopes fyniq.write.sales)."""
        return self.call("applyCustomerCredit", [], body, **options)

    def approve_purchase_order(self, purchase_order_id, **options):
        """Approve a purchase order (POST /v1/purchase-orders/{purchase_order_id}/approve; scopes fyniq.write.purchases)."""
        return self.call("approvePurchaseOrder", [purchase_order_id], None, **options)

    def auto_reconcile_bank_lines(self, body=None, **options):
        """Reconcile now (POST /v1/bank-lines:auto-reconcile; scopes fyniq.write.banking)."""
        return self.call("autoReconcileBankLines", [], body, **options)

    def back_test_bank_rule(self, body=None, **options):
        """Back-test bank rule conditions (POST /v1/bank-rules:back-test; scopes fyniq.read.banking, fyniq.write.banking)."""
        return self.call("backTestBankRule", [], body, **options)

    def bill_purchase_order(self, purchase_order_id, body=None, **options):
        """Make a bill from a purchase order (POST /v1/purchase-orders/{purchase_order_id}/bill; scopes fyniq.write.purchases)."""
        return self.call("billPurchaseOrder", [purchase_order_id], body, **options)

    def bulk_create_journals(self, body=None, **options):
        """Save up to 250 draft journals (POST /v1/journals:bulk; scopes fyniq.write.accounting)."""
        return self.call("bulkCreateJournals", [], body, **options)

    def cancel_invoice_payment_link(self, invoice_id, body=None, **options):
        """Cancel an invoice's live payment link (POST /v1/invoices/{invoice_id}/payment-link/cancellation; scopes fyniq.write.sales)."""
        return self.call("cancelInvoicePaymentLink", [invoice_id], body, **options)

    def cancel_quote(self, quote_id, body=None, **options):
        """Cancel a quote or sales order (POST /v1/quotes/{quote_id}/cancel; scopes fyniq.write.sales)."""
        return self.call("cancelQuote", [quote_id], body, **options)

    def capture_document(self, body=None, **options):
        """Capture a bill or a receipt (POST /v1/captures; scopes fyniq.write.purchases)."""
        return self.call("captureDocument", [], body, **options)

    def capture_from_message(self, body=None, **options):
        """Capture a file of accepted mail (POST /v1/captures/from-message; scopes fyniq.write.purchases)."""
        return self.call("captureFromMessage", [], body, **options)

    def categorise_bank_line(self, line_id, body=None, **options):
        """Categorise a bank line (POST /v1/bank-lines/{line_id}/categorise; scopes fyniq.write.banking)."""
        return self.call("categoriseBankLine", [line_id], body, **options)

    def close_purchase_order(self, purchase_order_id, body=None, **options):
        """Close a purchase order (POST /v1/purchase-orders/{purchase_order_id}/close; scopes fyniq.write.purchases)."""
        return self.call("closePurchaseOrder", [purchase_order_id], body, **options)

    def compare_forecast_scenarios(self, forecast_id, **options):
        """Compare a forecast's scenarios (GET /v1/forecasts/{forecast_id}/comparison; scopes fyniq.read.planning)."""
        return self.call("compareForecastScenarios", [forecast_id], None, **options)

    def complete_bank_transfer(self, transfer_id, body=None, **options):
        """Complete a transfer in transit (POST /v1/bank-transfers/{transfer_id}/complete; scopes fyniq.write.banking)."""
        return self.call("completeBankTransfer", [transfer_id], body, **options)

